/* Study Buddy Tahun 4: aplikasi statik tanpa dependensi luaran. */
(() => {
'use strict';
const KEY='study-buddy-tahun4-v3',e=SB.escape,$=id=>document.getElementById(id);
const fresh=()=>({version:3,stars:12,name:'',stats:{},scores:[],seen:{},practice:null,exam:null,bonusDate:null,activity:[],parentPin:''});
let storageBlocked=false,S;try{S=JSON.parse(localStorage.getItem(KEY)||'null')||fresh();if(S.version!==3||!Number.isFinite(S.stars)||!S.stats||!Array.isArray(S.scores)||!S.seen){storageBlocked=true;S=fresh();}}catch(err){storageBlocked=true;S=fresh();$('storage-warning').textContent='Rekod lama tidak dapat dibaca. Rekod asal tidak ditimpa. Eksport rekod sesi ini sebelum menutup halaman.';$('storage-warning').classList.remove('hide');}
S.activity=Array.isArray(S.activity)?S.activity:[];S.parentPin=typeof S.parentPin==='string'?S.parentPin:'';
document.body.classList.toggle('large-type',!!S.largeType);
// Sesi yang sedang berjalan menerima peraturan tambahan sahaja. Jawapan, markah
// lampau dan susunan pilihan dalam snapshot tidak diubah atau digred semula.
function enrichLive(questions){const current=[...Object.values(SB.banks).flat(),...Object.values(SB.papers).flatMap(p=>p.questions)];for(const q of questions||[]){const src=current.find(x=>x.id===q.id);if(!src)continue;q.contextKey??=src.contextKey;q.parts.forEach((p,i)=>{const base=src.parts.find(x=>x.label===p.label)||src.parts[p.category??i];if(!base)return;for(const key of ['wordTarget','contextWords','strictConcept','acceptedAnswers','guidance','requiredConcepts','conceptLabels','inference','observationConcepts','forbiddenConcepts'])if(base[key]!==undefined)p[key]=structuredClone(base[key]);});}}
enrichLive(S.practice?.questions);enrichLive(S.exam?.paper?.questions);
let page='home',selectedSubject=null,selectedTopic=null,examSubject='math',selectedSet=1,gallerySubject='all',scoreFilter='all',resultId=null,toastTimer,parentUnlocked=false;
const once=new WeakSet();[...Object.values(SB.banks).flat(),...Object.values(SB.papers).flatMap(p=>p.questions)].forEach(q=>q.parts.forEach(p=>{if(p.type!=='mcq'||once.has(p))return;once.add(p);let h=[...q.id].reduce((a,c)=>a+c.charCodeAt(0),0)%p.options.length;if(h){p.options=p.options.slice(h).concat(p.options.slice(0,h));p.answer=(p.answer-h+p.options.length)%p.options.length;}}));
const bank=sub=>SB.banks[sub].filter(q=>!q.id.startsWith('mx'));
const paperFor=record=>record.paper||SB.papers[record.subject+'-'+record.set];
const title=(h,p,action='')=>`<div class="page-heading"><div><div class="eyebrow">Rakan belajar Tahun 4</div><h1>${h}</h1>${p?`<p>${p}</p>`:''}</div>${action}</div>`;
function save(){S.scores.filter(s=>s.gradeVersion).forEach(s=>{const m=metrics(s);s.score=m.score;s.percentage=m.final?Math.round(m.score/50*100):null;s.finalScore=m.final?m.score:null;s.pendingMarks=m.pending;s.assessedTotal=m.assessedMax;s.scoreStatus=m.final?'final':'pending';});try{if(storageBlocked)throw Error('Rekod asal dilindungi');localStorage.setItem(KEY,JSON.stringify(S));$('saved-status').textContent='Tersimpan pada peranti';}catch(err){$('saved-status').textContent='Tidak dapat menyimpan';$('storage-warning').textContent='Penyimpanan peranti bermasalah. Rekod asal tidak ditimpa. Biarkan halaman ini terbuka dan eksport rekod. Jawapan baharu mungkin hilang jika halaman ditutup.';$('storage-warning').classList.remove('hide');}$('star-count').textContent=S.stars;}
function toast(msg){$('toast').textContent=msg;$('toast').classList.remove('hide');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.add('hide'),3500);}
function modal(html){$('modal-content').innerHTML=html;$('modal-close').classList.remove('hide');if(!$('modal').open)$('modal').showModal();}
$('modal-close').onclick=()=>$('modal').close();
function go(p){page=p;document.querySelectorAll('#main-nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));location.hash=p;render();}
function topicInfo(sub,id){return SB.topics[sub].find(x=>x.id===id);}
function statPct(stat){return stat?.max?Math.round(stat.marks/stat.max*100):null;}
function weakest(){return Object.entries(S.stats).filter(([,v])=>v.total).sort(([,a],[,b])=>statPct(a)-statPct(b));}
function logActivity(type,data={}){S.activity.push({id:"ev-"+Date.now()+"-"+Math.random().toString(36).slice(2,7),type,at:new Date().toISOString(),name:S.name||"Murid",...data});if(S.activity.length>3000)S.activity=S.activity.slice(-3000);}
function fmtTime(value){return new Date(value).toLocaleString("ms-MY",{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"});}
function parent(){
if(!S.parentPin)return title("Ruang Ibu Bapa","Tetapkan PIN 4 digit untuk melindungi laporan kemajuan.")+"<section class=\"card parent-lock\"><h2>Aktifkan Parent Tracking</h2><p class=\"muted\">Rekod terperinci bermula selepas kemas kini ini. Rekod prestasi lama masih dikekalkan.</p><label for=\"new-parent-pin\">PIN baharu</label><input id=\"new-parent-pin\" type=\"password\" inputmode=\"numeric\" maxlength=\"4\" pattern=\"[0-9]{4}\" placeholder=\"4 digit\"><button class=\"primary spaced\" data-set-parent-pin>Simpan PIN</button></section>";
if(!parentUnlocked)return title("Ruang Ibu Bapa","Masukkan PIN untuk melihat aktiviti pembelajaran.")+"<section class=\"card parent-lock\"><label for=\"parent-pin\">PIN ibu bapa</label><input id=\"parent-pin\" type=\"password\" inputmode=\"numeric\" maxlength=\"4\" placeholder=\"••••\"><button class=\"primary spaced\" data-unlock-parent>Buka laporan</button></section>";
const now=Date.now(),todayStart=new Date().setHours(0,0,0,0),weekStart=now-7*86400000,answers=S.activity.filter(x=>x.type==="practice_answer"),today=answers.filter(x=>new Date(x.at).getTime()>=todayStart),week=answers.filter(x=>new Date(x.at).getTime()>=weekStart),todayCorrect=today.filter(x=>x.correct).length,todaySeconds=today.reduce((a,x)=>a+(Number(x.seconds)||0),0),exits=S.activity.filter(x=>x.type==="app_hidden"&&new Date(x.at).getTime()>=todayStart).length;
const subjectRows=Object.entries(SB.subjects).map(([id,sub])=>{const events=answers.filter(x=>x.subject===id),correct=events.filter(x=>x.correct).length,legacy=Object.entries(S.stats).filter(([k])=>k.startsWith(id+":")).reduce((a,[,v])=>a+(v.total||0),0),topics=SB.topics[id].map(t=>{const ev=events.filter(x=>x.topic===t.id),st=S.stats[id+":"+t.id];return {name:t.name,count:ev.length,responses:st?.total||0,pct:st?statPct(st):null,last:ev.at(-1)?.at||st?.last};}).filter(x=>x.count||x.responses).sort((a,b)=>(b.last||0)-(a.last||0));return "<div class=\"card parent-subject\"><div class=\"row\"><h2>"+e(sub.name)+"</h2><b>"+events.length+" soalan direkod</b></div><p class=\"muted\">"+legacy+" respons dinilai keseluruhan"+(events.length?" · "+Math.round(correct/events.length*100)+"% soalan tepat":"")+"</p><div class=\"topic-stats\">"+(topics.map(t=>"<div class=\"topic-stat\"><div class=\"row\"><span>"+e(t.name)+"</span><b>"+(t.pct===null?"—":t.pct+"%")+"</b></div><small>"+t.count+" soalan terperinci · "+t.responses+" respons dinilai"+(t.last?" · terakhir "+fmtTime(t.last):"")+"</small></div>").join("")||"<p class=\"muted\">Belum ada latihan.</p>")+"</div></div>";}).join("");
const current=S.practice?"Latihan "+SB.subjects[S.practice.subject].name+" · "+topicInfo(S.practice.subject,S.practice.topic).name+" · "+Math.min(S.practice.index+1,S.practice.questions.length)+"/"+S.practice.questions.length:S.exam?"Exam "+SB.subjects[S.exam.subject].name+" · Set "+S.exam.set+" · soalan "+(S.exam.index+1)+"/"+paperFor(S.exam).questions.length:"Tiada sesi tergantung";
const recent=S.activity.filter(x=>x.type==="practice_answer"||x.type==="exam_submit").slice(-20).reverse();
return title("Dashboard Ibu Bapa","Kemajuan sebenar berdasarkan jawapan yang dihantar, bukan sekadar aplikasi dibuka.","<button class=\"secondary\" data-lock-parent>Kunci</button>")+"<section class=\"card parent-profile\"><label for=\"child-name\">Nama anak</label><div class=\"row\"><input id=\"child-name\" maxlength=\"60\" value=\""+e(S.name)+"\" placeholder=\"Nama anak\"><button class=\"secondary\" data-save-child>Simpan</button></div><p class=\"muted spaced\"><b>Sesi semasa:</b> "+e(current)+"</p></section><div class=\"grid-four spaced\"><div class=\"card\"><div class=\"stat-number\">"+today.length+"</div><div class=\"stat-label\">Soalan hari ini</div></div><div class=\"card\"><div class=\"stat-number\">"+todayCorrect+"</div><div class=\"stat-label\">Betul hari ini</div></div><div class=\"card\"><div class=\"stat-number\">"+week.length+"</div><div class=\"stat-label\">Soalan 7 hari</div></div><div class=\"card\"><div class=\"stat-number\">"+Math.round(todaySeconds/60)+" min</div><div class=\"stat-label\">Masa menjawab · keluar app "+exits+"×</div></div></div><div class=\"parent-grid spaced\">"+subjectRows+"</div><section class=\"card spaced\"><h2>Aktiviti terkini</h2><p class=\"muted\">“Keluar app” bermaksud Study Buddy masuk latar belakang; ia tidak dapat mengetahui aplikasi lain yang dibuka.</p><div class=\"activity-list\">"+(recent.map(x=>"<div class=\"activity-row\"><span><b>"+e(x.type==="exam_submit"?"Simulasi dihantar":SB.subjects[x.subject]?.name||"Latihan")+"</b><small>"+(x.type==="exam_submit"?"Set "+x.set+" · "+x.score+"/50":e(topicInfo(x.subject,x.topic)?.name||x.topic)+" · "+(x.correct?"Betul":"Perlu ulang")+(x.hints?" · hint "+x.hints:""))+"</small></span><time>"+fmtTime(x.at)+"</time></div>").join("")||"<p class=\"muted\">Aktiviti terperinci akan muncul selepas anak menjawab soalan.</p>")+"</div></section>";
}
function subjectCards(type){return `<div class="grid">${Object.entries(SB.subjects).map(([id,s])=>`<button class="subject-card" data-${type}="${id}"><span class="subject-icon ${s.color}">${s.icon}</span><span><strong>${e(s.name)}</strong><small>${e(s.description)}</small><small>${type==='subject'?bank(id).length+' item latihan · '+SB.topics[id].length+' topik':'2 set · 50 markah · 75 minit'}</small></span><span class="arrow">→</span></button>`).join('')}</div>`;}
function home(){let weak=weakest()[0],w=weak?weak[0].split(':'):null,total=Object.keys(SB.banks).reduce((a,s)=>a+bank(s).length,0);return title('Nak belajar apa hari ini?','Pilih subjek dan terus mula. Lima situasi setiap sesi, banyak variasi untuk sesi seterusnya.')+subjectCards('subject')+`<div class="home-note"><div><span class="pill">Latihan penuh</span><h3>Biasakan diri dengan kertas MPT4</h3><p class="muted">Pilih Set 1 atau Set 2. Setiap subjek mempunyai struktur sendiri.</p></div><button class="primary" data-page="exam">Pilih simulasi →</button></div><div class="grid spaced"><div class="card"><h3>${w?'Topik untuk ulang':'Mulakan dengan satu langkah'}</h3><p class="muted">${w?e(SB.subjects[w[0]].name+' · '+topicInfo(w[0],w[1]).name)+' — ketepatan '+statPct(weak[1])+'%.':'Cuba Sains Pemboleh Ubah jika masih keliru antara perkara yang diubah, diukur dan dikekalkan.'}</p><button class="text-button" data-quick="${w?w.join(':'):'science:variables'}">Cuba sesi pendek →</button></div><div class="card"><h3>Rekod pada peranti ini</h3><p class="muted">${S.scores.length} cubaan simulasi · ${SB.sources.length} gambar rujukan · ${total} item dalam bank soalan.</p><div class="actions"><button class="secondary" data-page="performance">Lihat prestasi</button><button class="text-button" data-bonus>${S.bonusDate===new Date().toLocaleDateString('en-CA')?'Bonus hari ini sudah diambil':'Ambil bonus harian +3 ★'}</button></div></div></div>`;}
function practice(){if(S.practice)return renderPractice();if(!selectedSubject)return title('Latih Tubi Topik','Bank besar, sesi pendek. Setiap topik ada penerangan, contoh, petunjuk dan latihan.')+subjectCards('subject');const s=SB.subjects[selectedSubject];if(!selectedTopic)return title(e(s.name),'Pilih topik. Soalan menggunakan bentuk respons dan bahan seperti latihan peperiksaan.',`<button class="secondary" data-practice-back>← Subjek</button>`)+`<div class="card"><h2>Topik Tahun 4</h2><div class="topic-list">${SB.topics[selectedSubject].map(t=>{let stats=S.stats[selectedSubject+':'+t.id],pct=statPct(stats),pool=bank(selectedSubject).filter(q=>q.topic===t.id);return `<button class="topic-button" data-topic="${t.id}"><strong>${e(t.name)}</strong><small>${pool.length} item latihan · ${pct===null?'Belum dicuba':pct+'% ketepatan · '+stats.total+' soalan kecil dicuba'}</small>${pct!==null&&pct<65?'<span class="pill amber">Boleh ulang lagi</span>':''}</button>`;}).join('')}</div></div>`;
const t=topicInfo(selectedSubject,selectedTopic),n=bank(selectedSubject).filter(q=>q.topic===selectedTopic).length;return title(e(t.name),'Baca contoh, kemudian cuba lima situasi.',`<button class="secondary" data-topic-back>← Topik</button>`)+`<div class="lesson-layout"><div class="card"><h2>Faham konsep dahulu</h2><div class="lesson-teach"><p>${e(t.teach)}</p></div><div class="lesson-example"><b>Demonstrasi cara berfikir</b><p>${e(t.example)}</p></div><div class="actions"><button class="primary" data-start-practice>Mula sesi 5 situasi →</button></div><p class="muted spaced">${n} situasi tersedia. Soalan yang belum pernah dicuba akan diutamakan.</p></div>${buddy('Cuba baca contoh dengan suara perlahan. Apabila bersedia, kita jawab satu situasi pada satu masa.')}</div>`;}
function shuffle(arr){let a=arr.slice();for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function choose(sub,topic,n=5,except=[]){let pool=bank(sub).filter(q=>q.topic===topic&&!except.includes(q.id)),seen=S.seen[sub+':'+topic]||[],ordered=shuffle(pool.filter(q=>!seen.includes(q.id))).concat(shuffle(pool.filter(q=>seen.includes(q.id)))),contexts=new Set(),picked=[];for(const q of ordered){if(!contexts.has(q.contextKey)){picked.push(q);contexts.add(q.contextKey);if(picked.length===n)return picked;}}return picked.concat(ordered.filter(q=>!picked.includes(q))).slice(0,n);}
function startPractice(){const sub=selectedSubject,topic=selectedTopic;let qs=choose(sub,topic);if(!qs.length){toast('Belum ada soalan untuk topik ini.');return;}if(sub==='science'&&topic==='variables'){let categories=S.stats['science:variables']?.categories||{},weak=Object.entries(categories).filter(([,x])=>x.total).sort(([,a],[,b])=>a.correct/a.total-b.correct/b.total)[0];if(weak&&weak[1].correct/weak[1].total<.7){let pos=Number(weak[0]);qs=qs.map((q,i)=>({...q,parts:[{...q.parts[pos],category:pos},{...q.parts[(pos+1+i%3)%4],category:(pos+1+i%3)%4}]}));}}
S.practice={subject:sub,topic,questions:qs,index:0,answers:{},hints:{},graded:{},rewards:{},started:Date.now()};logActivity('practice_start',{subject:sub,topic,total:qs.length});save();go('practice');}
function buddy(text,hints=[]){return `<aside class="card side-card"><div class="buddy-avatar">✦</div><h3>Rakan Study</h3><p class="buddy-message spaced">${e(text)}</p>${hints.length?`<ol class="hint-list">${hints.map((h,i)=>`<li><b>Hint ${i+1}</b><br>${e(h)}</li>`).join('')}</ol>`:''}<p class="muted spaced">Betul tanpa hint: +3 ★<br>Betul dengan hint: +1 ★</p><p class="muted">Semua hint percuma. Minta bantuan bila perlu—bintang tidak ditolak.</p></aside>`;}
function questionBody(q,answers,key,readonly=false){return `<div class="question-heading">${e(q.stem)}</div>${q.en?`<p class="translation">${e(q.en)}</p>`:''}${q.passage?`<div class="passage"><h3>${e(q.title||'Petikan / Passage')}</h3>${e(q.passage)}</div>`:''}<div id="diagram-${key}">${SB.diagram(q.diagram,{interactive:!readonly,key,answers})}</div>${q.diagram&&!['image','scene'].includes(q.diagram.type)?`<button class="text-button" data-zoom="${key}">Besarkan rajah (paparan penuh)</button>`:''}${q.sourceImage?`<button class="text-button" data-image="${e(q.sourceImage)}">Lihat gambar rujukan asal</button>`:''}${q.parts.map((p,i)=>renderPart(p,answers?.[i]||{},key,i,readonly)).join('')}`;}
function renderPart(p,a,key,i,readonly){const id=key+'-'+i,val=e(a.value??''),disabled=readonly?'disabled':'',ro=readonly?'readonly':'';let control='';const common=`data-answer="${key}" data-part="${i}"`;
if(p.type==='mcq')control=`<div class="choice-list">${p.options.map((x,j)=>`<label class="choice"><input type="radio" name="${id}" value="${j}" ${common} data-field="value" ${String(a.value)===String(j)?'checked':''} ${disabled}><span><b>${String.fromCharCode(65+j)}.</b> ${e(x)}</span></label>`).join('')}</div>`;
else if(p.type==='coordinate')control=`<div class="field-line"><input id="${id}" aria-label="${e(p.label)} nilai x" type="number" inputmode="numeric" min="0" max="6" placeholder="x" value="${e(a.x??'')}" ${common} data-field="x" ${ro}><input aria-label="Koordinat nilai y" type="number" inputmode="numeric" min="0" max="6" placeholder="y" value="${e(a.y??'')}" ${common} data-field="y" ${ro}></div>`;
else if(p.type==='number')control=`<div class="field-line"><input type="text" inputmode="decimal" id="${id}" aria-label="${e(p.label)}" placeholder="Jawapan / Answer" value="${val}" ${common} data-field="value" ${ro}>${p.unit?`<input class="unit-field" type="text" aria-label="Unit jawapan" placeholder="Unit" value="${e(a.unit||'')}" ${common} data-field="unit" ${ro}>`:''}</div>${p.steps?.length?`<label class="work-label" for="work-${id}">Langkah kerja / Working (markah separa mengikut rubrik)</label><textarea id="work-${id}" ${common} data-field="work" placeholder="Contoh format: 12 × 4 = 48. Tulis langkah kamu sendiri." ${ro}>${e(a.work||'')}</textarea>`:''}`;
else control=`<textarea id="${id}" aria-label="${e(p.label)}" ${common} data-field="value" class="${p.type==='essay'?'essay':''}" placeholder="${key.startsWith('en')?'Write your answer here.':'Tulis jawapan di sini / Write your answer here.'}" ${ro}>${val}</textarea>${p.type==='essay'?`<div class="word-count" id="wc-${id}">${wordCount(p,a.value||'')}</div><div class="checklist"><b>Checklist sebelum hantar</b>${p.keywords.map((g,j)=>`<label><input type="checkbox" data-check="${key}" data-part="${i}" data-check-index="${j}" ${a.checks?.[j]?'checked':''} ${disabled}> Isi / Idea: ${e(g[0])}</label>`).join('')}<label><input type="checkbox" ${disabled}> Huruf besar, tanda baca dan ejaan sudah disemak.</label></div>`:''}`;
if(!readonly&&key.startsWith('p-')&&S.practice?.subject==='science'&&p.strictConcept){const source=SB.banks.science.find(q=>q.id===S.practice.questions[S.practice.index].id),choices=[...new Set((source?.parts||[]).filter(x=>x.strictConcept).map(x=>x.answer))].sort();control=`<div class="word-bank" aria-label="Bank kata pemboleh ubah"><small>Tekan pilihan atau tulis sendiri. Bank kata dikira bantuan.</small><div>${choices.map(x=>`<button class="chip" data-chip="${e(x)}" data-key="${key}" data-part="${i}" aria-pressed="${a.value===x}">${e(x)}</button>`).join('')}</div></div>`+control;}
return `<div class="part"><label class="part-label" for="${id}">${e(p.label)} <span class="part-mark">[${p.marks} markah / marks]</span></label>${control}</div>`;}
function wordCount(p,v){let n=v.trim().split(/\s+/).filter(Boolean).length,status=n<p.min?'Belum cukup':n>p.max?'Terlalu panjang':'Dalam julat';return `<span>${n} patah perkataan / words</span><span class="${n>=p.min&&n<=p.max?'in-range':'outside'}">${status} · ${p.min===1?'≤ '+p.max:p.min+'–'+p.max}</span>`;}
function feedback(q,g){return `<div class="feedback ${g.correct===false||g.score<g.max?'needs-work':'correct-pop'}"><b>${g.pending?'Markah akhir belum ditentukan.':(g.correct??g.score===g.max)?'Jawapan kamu betul.':'Mari semak bahagian yang perlu diperbaiki.'}</b>${g.pending?`<p>Markah automatik: ${g.score}/${g.assessedMax} untuk komponen yang telah dinilai. Menunggu semakan ibu bapa: ${g.pending} markah.</p>`:''}${g.parts.map((p,i)=>`<p class="spaced"><b>${e(q.parts[i].label)}</b><br>${e(p.message||'Semak komponen di bawah.')}</p><ul class="rubric">${p.details.map(d=>`<li><span>${e(d.label)}</span><span>${d.pending?'Menunggu semakan ibu bapa /'+d.max:d.earned+'/'+d.max}</span></li>`).join('')}</ul>`).join('')}<details class="sample-answer"><summary>Tengok Contoh Jawapan &amp; Penyelesaian</summary><p class="spaced">${e(q.explanation||'Semak maksud jawapan, bukan hafal ayat contoh.')}</p>${g.parts.map((p,i)=>`<p class="spaced"><b>${e(q.parts[i].label)}</b><br>${q.parts[i].type==='essay'?'Gunakan checklist dan semakan ibu bapa.':e(p.answer)}</p>`).join('')}${page==='practice'?'<button class="secondary spaced" data-self-check>Adakah maksud jawapan saya sama?</button><p class="muted">Semakan kendiri tidak mengubah markah atau memberi bintang tambahan.</p>':''}</details>${g.review?'<p class="muted spaced">Respons terbuka dan isi dikesan ialah cadangan; ibu bapa boleh semak.</p>':''}</div>`;}
function practiceClock(){const P=S.practice;if(!P||P.index>=P.questions.length||P.graded[P.index])return null;P.clocks??={};if(!P.clocks[P.index]){const q=P.questions[P.index],read=SB.readingBudget(q),already=Object.values(P.clocks).some(c=>c.passage===q.passage&&q.passage);P.clocks[P.index]={phase:read&&!already?'reading':'answer',passage:q.passage||null,limit:SB.practiceBudget(q),started:Date.now(),deadline:Date.now()+(read&&!already?read:SB.practiceBudget(q))*1000};save();}return P.clocks[P.index];}
function beginAnswerClock(){const c=practiceClock();if(!c||c.phase!=='reading')return;c.phase='answer';c.started=Date.now();c.deadline=Date.now()+c.limit*1000;save();render();}
function tickPractice(){const P=S.practice;if(!P||P.index>=P.questions.length||P.graded[P.index])return;const c=practiceClock();if(Date.now()>=c.deadline){if(c.phase==='reading')beginAnswerClock();else checkPractice(true);return;}if($('practice-timer'))$('practice-timer').textContent=timeLeft(c.deadline);}
function starAnimation(){const badge=document.querySelector('.star-badge');badge.classList.remove('star-earned');void badge.offsetWidth;badge.classList.add('star-earned');}
function resolvedGrade(s,i){let g=structuredClone(s.grades[i]);if(Object.hasOwn(s.adjustments||{},i)){g.score=Number(s.adjustments[i]);g.pending=0;g.assessedMax=g.max;g.finalScore=g.score;g.parentTotal=true;g.correct=g.score===g.max;return g;}if(!s.gradeVersion)return g;g.parts.forEach((p,j)=>{p.details.forEach((d,k)=>{const v=s.manualMarks?.[i]?.[j]?.[k];if(d.pending&&v!==undefined){d.earned=v;d.pending=false;}});p.score=p.details.reduce((a,d)=>a+(d.earned??0),0);p.pending=p.details.reduce((a,d)=>a+(d.pending?d.max:0),0);p.assessedMax=p.max-p.pending;});g.score=g.parts.reduce((a,p)=>a+p.score,0);g.pending=g.parts.reduce((a,p)=>a+(p.pending||0),0);g.assessedMax=g.max-g.pending;g.correct=g.pending===0&&g.score===g.max&&!g.parts.some(p=>p.workConflict);return g;}
function metrics(s){if(!s.gradeVersion)return {score:s.score,pending:0,assessedMax:50,final:true};const grades=s.grades.map((_,i)=>resolvedGrade(s,i)),score=grades.reduce((a,g)=>a+g.score,0),pending=grades.reduce((a,g)=>a+(g.pending||0),0);return {score,pending,assessedMax:50-pending,final:pending===0};}
function scoreText(s){const m=metrics(s);return m.final?m.score+'/50':m.score+'/'+m.assessedMax+' dinilai · menunggu '+m.pending;}
function manualFields(s,i){if(!s.gradeVersion||Object.hasOwn(s.adjustments||{},i))return '';const g=resolvedGrade(s,i);return g.parts.map((p,j)=>p.details.map((d,k)=>s.grades[i].parts[j].details[k].pending?`<label class="manual-component">${e(d.label)} (0–${d.max})<input type="number" inputmode="decimal" min="0" max="${d.max}" step="0.5" id="manual-${i}-${j}-${k}" value="${s.manualMarks?.[i]?.[j]?.[k]??''}" placeholder="Belum dinilai"><button class="secondary" data-manual="${i}:${j}:${k}" data-result="${s.id}">Simpan komponen</button></label>`: '').join('')).join('');}

function renderPractice(){let P=S.practice;if(P.index>=P.questions.length)return practiceSummary(P);let q=P.questions[P.index],key='p-'+P.index,graded=P.graded[P.index],h=P.hints[P.index]||0,c=practiceClock(),reading=c?.phase==='reading';return title(e(SB.subjects[P.subject].name)+' · '+e(topicInfo(P.subject,P.topic).name),'Latihan berpemasa · hint percuma',`<button class="secondary" data-leave-practice>Simpan & pilih aktiviti lain</button>`)+`<div class="lesson-layout"><section class="card ${reading?'reading-stage':''}"><div class="row"><span class="pill">Situasi ${P.index+1} / ${P.questions.length}</span>${graded?'<span class="pill amber">'+(graded.solutionViewed?'Belajar penyelesaian':graded.expired?'Masa tamat':graded.withinTime?'Dijawab dalam masa':'Latihan semula')+'</span>':`<div class="practice-clock" role="timer"><small>${reading?'Masa membaca':'Masa menjawab · '+(c.limit/60)+' min maks.'}</small><div class="timer" id="practice-timer">${timeLeft(c.deadline)}</div></div>`}</div><div class="progress"><span style="width:${P.index/P.questions.length*100}%"></span></div>${questionBody(q,P.answers[P.index],key,!!graded)}${graded?feedback(q,graded):''}<div class="actions">${reading?'<button class="primary" data-finish-reading>Dah baca — mula jawab →</button>':graded?`<button class="primary" data-next-practice>${P.index===P.questions.length-1?'Lihat ringkasan':'Situasi seterusnya →'}</button><button class="secondary" data-related>Cuba situasi konsep sama</button><button class="secondary" data-retry>Cuba semula untuk belajar</button>`:`<button class="primary" data-check-practice>Semak jawapan</button><button class="hint-button" data-hint ${h>=3?'disabled':''}>💡 ${h>=3?'Semua hint dibuka':'Hint '+(h+1)+' · percuma'}</button><button class="text-button" data-worked>Lihat penyelesaian selepas semak</button>`}</div></section>${buddy(graded?'Semak sebab dan langkah, kemudian cuba situasi baharu.':reading?'Baca petikan dahulu. Tekan mula jawab apabila bersedia.':'Cari maklumat penting dan jawab sebelum masa tamat. Hint sentiasa percuma.',q.hints?.slice(0,h)||[])}</div>`;}

function answeredPart(p,a){return p.type==='coordinate'?a?.x!==undefined&&a.x!==''&&a?.y!==undefined&&a.y!=='':a?.value!==undefined&&String(a.value).trim()!=='';}
function checkPractice(expired=false,solution=false){let P=S.practice,q=P.questions[P.index];if(P.graded[P.index])return;if(!expired&&!q.parts.every((p,i)=>answeredPart(p,P.answers[P.index]?.[i]))){toast('Cuba isi setiap bahagian dahulu. Hint tersedia jika perlu.');return;}let g=SB.gradeQuestion(q,P.answers[P.index]),c=practiceClock();g.expired=expired&&!solution;g.solutionViewed=solution;g.withinTime=!expired&&Date.now()<=c.deadline&&!c.retry;g.seconds=Math.round((Date.now()-c.started)/1000);P.graded[P.index]=g;P.recorded??={};const first=!P.recorded[q.id];P.recorded[q.id]=true;let sk=P.subject+':'+P.topic,stats=S.stats[sk]||{correct:0,total:0,marks:0,max:0,categories:{}};if(first)g.parts.forEach((r,i)=>{stats.correct+=(r.correct??r.score===r.max)?1:0;stats.total++;stats.marks+=r.score;stats.max+=r.assessedMax??r.max;if(P.subject==='science'&&P.topic==='variables'){let k=q.parts[i].category??i;let c=stats.categories[k]||{correct:0,total:0};c.total++;c.correct+=r.score===r.max?1:0;stats.categories[k]=c;}});stats.last=Date.now();S.stats[sk]=stats;S.seen[sk]=[...new Set([...(S.seen[sk]||[]),q.id])];if(first)logActivity('practice_answer',{subject:P.subject,topic:P.topic,questionId:q.id,correct:!!(g.correct??g.score===g.max),score:g.score,max:g.max,hints:P.hints[P.index]||0,seconds:g.seconds||0,expired:!!g.expired});if(!P.rewards[q.id]){let reward=!expired&&!P.revealed?.[P.index]&&(g.correct??g.score===g.max)?(P.hints[P.index]||P.assisted?.[P.index]?1:3):0;S.stars+=reward;P.rewards[q.id]=true;if(reward){toast('Usaha yang baik! +'+reward+' ★');starAnimation();}}save();render();if(expired&&!solution)toast('Masa tamat. Jawapan kamu disimpan; mari belajar daripada semakan.');}
function practiceSummary(P){let grades=Object.values(P.graded),earned=grades.reduce((a,x)=>a+x.score,0),max=grades.reduce((a,x)=>a+x.max,0),categories=S.stats['science:variables']?.categories||{};return title('Sesi selesai. Bagus terus mencuba!','Kamu boleh ulang dengan situasi berbeza.')+`<div class="card"><span class="pill">${e(SB.subjects[P.subject].name)}</span><div class="result-score spaced">${earned} / ${grades.reduce((a,g)=>a+(g.assessedMax??g.max),0)} dinilai</div><p class="muted">${grades.filter(g=>g.withinTime&&(g.correct??g.score===g.max)).length}/${grades.length} situasi betul dalam masa. Respons terbuka ialah cadangan.${grades.some(g=>g.pending)?' Jumlah akhir penulisan belum ditentukan; komponen manual tidak dikira sebagai sifar.':''}</p>${P.subject==='science'&&P.topic==='variables'?`<div class="topic-stats">${['Dimanipulasikan','Bergerak balas','Dimalarkan','Inferens'].map((c,i)=>{const st=categories[i];return `<div class="topic-stat">${c}: ${st?.total?Math.round(st.correct/st.total*100)+'% betul ('+st.correct+'/'+st.total+')':'Belum dicuba'}</div>`;}).join('')}</div><p class="muted spaced">Sesi seterusnya memberi lebih banyak latihan pada kategori yang kerap tersilap.</p>`:''}<div class="actions"><button class="primary" data-repeat-practice>Sesi baharu / latihan pemulihan percuma</button><button class="secondary" data-finish-practice>Pilih topik lain</button></div></div>`;}
function formatSummary(p){return `<div class="format-summary">${p.sections.map(s=>`<div class="format-row"><span>${e(s.name)} · ${s.count} soalan / situasi</span><strong>${s.marks} markah</strong></div>`).join('')}<div class="format-row"><strong>Jumlah</strong><strong>50 markah · 75 minit</strong></div></div>`;}
function exam(){if(resultId)return resultView(resultId);if(S.exam)return renderExam();const p=SB.papers[examSubject+'-'+selectedSet];return title('Simulasi kertas penuh MPT4','Set 1 dan Set 2 berbeza. Nama wajib diisi sebelum masa bermula.')+`<div class="lesson-layout"><section class="card"><label class="selection-label" for="name">Nama murid</label><input id="name" type="text" maxlength="60" placeholder="Nama kamu" value="${e(S.name)}"><label class="selection-label" for="exam-subject">Subjek</label><select id="exam-subject">${Object.entries(SB.subjects).map(([id,s])=>`<option value="${id}" ${id===examSubject?'selected':''}>${e(s.name)}</option>`).join('')}</select><div class="selection-label">Nombor set</div><div class="set-options">${[1,2].map(n=>`<label class="set-choice"><input type="radio" name="set" value="${n}" ${n===selectedSet?'checked':''}> <b>Set ${n}</b><br><span class="muted">Kandungan berbeza</span></label>`).join('')}</div>${formatSummary(p)}<div class="lesson-teach"><b>Arahan sebelum mula</b><p>Jawab semua bahagian. Kamu boleh berpindah soalan dan menanda untuk semakan. Jawapan disimpan automatik. Masa tetap berjalan jika halaman ditutup. Semak soalan belum dijawab sebelum menghantar.</p></div><div class="actions"><button class="primary" data-begin-exam>Mula 75 minit →</button></div></section><aside class="card side-card"><span class="pill">${e(SB.subjects[examSubject].name)}</span><h3 class="spaced">Tenang dan teratur</h3><p class="buddy-message spaced">Baca arahan setiap bahagian. Matematik memerlukan jawapan sendiri dan langkah kerja. Penulisan serta respons terbuka disertai rubrik dan semakan ibu bapa.</p><p class="muted spaced">Soalan latihan untuk persediaan; bukan kertas rasmi atau soalan sebenar.</p></aside></div>`;}
function beginExam(){let name=$('name').value.trim();if(!name){$('name').focus();toast('Isi nama murid dahulu ya.');return;}S.name=name;let now=Date.now();S.exam={subject:examSubject,set:selectedSet,name,paper:structuredClone(SB.papers[examSubject+'-'+selectedSet]),start:now,deadline:now+4500000,index:0,answers:{},flags:{}};logActivity('exam_start',{subject:examSubject,set:selectedSet});save();render();}
function questionLabel(q){let s=q.section.startsWith('Part')?'P'+q.section.replace('Part ',''):q.section.replace('Bahagian ','');return s+'-'+q.number;}
function questionComplete(q,answers){return q.parts.every((p,i)=>answeredPart(p,answers?.[i]));}
function mapHTML(){let X=S.exam,p=paperFor(X);return p.questions.map((q,i)=>`<button data-exam-index="${i}" class="${questionComplete(q,X.answers[i])?'answered':''} ${X.flags[i]?'flagged':''} ${i===X.index?'current':''}" aria-label="${questionLabel(q)} ${questionComplete(q,X.answers[i])?'sudah jawab':'belum lengkap'}${X.flags[i]?' semak semula':''}">${questionLabel(q)}</button>`).join('');}
function renderExam(){let X=S.exam,p=paperFor(X),q=p.questions[X.index],sec=p.sections.find(x=>x.name===q.section);return `<div class="exam-top"><div><div class="eyebrow">${e(X.name)} · Set ${X.set} · 50 markah</div><h1>${e(SB.subjects[X.subject].name)}</h1></div><div><small class="muted">Baki masa</small><div class="timer" id="timer">${timeLeft(X.deadline)}</div></div></div><div class="section-tabs">${p.sections.map(s=>`<button data-section="${e(s.name)}" class="${s.name===q.section?'active':''}">${e(s.name)}</button>`).join('')}</div><div class="exam-layout"><section class="card"><div class="row"><span class="pill">${e(q.section)} · Soalan ${q.number}</span><span class="muted">${q.marks} markah</span></div><p class="muted spaced">${e(sec.instructions)}</p><div class="spaced">${questionBody(q,X.answers[X.index],'x-'+X.index)}</div><label class="review-label"><input id="flag" type="checkbox" ${X.flags[X.index]?'checked':''}> Tandakan untuk semak semula</label><div class="actions"><button class="secondary" data-exam-prev ${X.index===0?'disabled':''}>← Sebelum</button><button class="primary" data-exam-next ${X.index===p.questions.length-1?'disabled':''}>Seterusnya →</button><button class="text-button" data-submit-confirm>Semak & hantar</button></div></section><aside class="card side-card"><h3>Navigasi soalan</h3><div id="question-map" class="question-map">${mapHTML()}</div><p class="muted">Hijau: lengkap<br>●: semak semula<br>Kelabu: belum lengkap</p><p class="muted spaced" id="remaining-label"></p><button class="secondary spaced" data-submit-confirm>Semak & hantar</button><p class="muted spaced">Jawapan disimpan pada peranti ini.</p></aside></div>`;}
function timeLeft(deadline){let t=Math.max(0,Math.ceil((deadline-Date.now())/1000));return String(Math.floor(t/3600)).padStart(2,'0')+':'+String(Math.floor(t%3600/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');}
function updateExamMap(){if(!S.exam)return;let p=paperFor(S.exam),left=p.questions.filter((q,i)=>!questionComplete(q,S.exam.answers[i])).length;if($('question-map'))$('question-map').innerHTML=mapHTML();if($('remaining-label'))$('remaining-label').textContent=left+' soalan belum lengkap daripada '+p.questions.length;}
function confirmSubmit(){let X=S.exam,p=paperFor(X),left=p.questions.filter((q,i)=>!questionComplete(q,X.answers[i])).length,flag=Object.values(X.flags).filter(Boolean).length;modal(`<h2>Semak sebelum hantar</h2><p>${left} soalan belum lengkap. ${flag} soalan ditanda untuk semakan.</p><p class="muted spaced">Selepas dihantar, kamu akan melihat keputusan, rubrik dan analisis topik.</p><div class="actions"><button class="primary" data-submit-final>Ya, hantar jawapan</button><button class="secondary" data-return-exam>Teruskan menjawab</button></div>`);}
function submitExam(expired=false){if(!S.exam)return;let X=S.exam,p=paperFor(X),grades=p.questions.map((q,i)=>SB.gradeQuestion(q,X.answers[i]));let score=grades.reduce((a,g)=>a+g.score,0);let attempt=S.scores.filter(s=>s.name===X.name&&s.subject===X.subject&&s.set===X.set).length+1;let id='attempt-'+Date.now();S.scores.unshift({id,paper:p,name:X.name,subject:X.subject,set:X.set,attempt,score,total:50,percentage:Math.round(score/50*100),time:Math.min(4500,Math.round((Date.now()-X.start)/1000)),date:new Date().toISOString(),answers:X.answers,grades,gradeVersion:4,manualMarks:{},adjustments:{},expired});logActivity('exam_submit',{subject:X.subject,set:X.set,score,total:50,seconds:Math.min(4500,Math.round((Date.now()-X.start)/1000)),expired:!!expired});S.exam=null;resultId=id;save();$('modal').close();go('exam');if(expired)toast('Masa selesai. Jawapan yang tersimpan telah dihantar.');}
function adjustedGrade(s,i){return resolvedGrade(s,i).score;}
function analysis(s){let p=paperFor(s),topics={};p.questions.forEach((q,i)=>{let t=topics[q.topic]||{score:0,max:0};t.score+=adjustedGrade(s,i);t.max+=q.marks;t.pending=(t.pending||0)+(resolvedGrade(s,i).pending||0);topics[q.topic]=t;});return topics;}
function resultView(id){let s=S.scores.find(x=>x.id===id);if(!s){resultId=null;return exam();}let p=paperFor(s),review=s.grades.some(g=>g.review),m=metrics(s);return title('Keputusan & langkah seterusnya',e(s.name)+' · '+e(SB.subjects[s.subject].name)+' · Set '+s.set+' · Cubaan '+s.attempt,`<button class="secondary" data-result-back>← Scoreboard</button>`)+`<div class="grid"><section class="card"><span class="pill amber">${review?'Cadangan markah — semakan ibu bapa tersedia':'Semakan jawapan automatik'}</span><div class="result-score spaced" id="result-score">${m.final?m.score+' / 50':m.score+' / '+m.assessedMax+' dinilai'}</div><p class="muted">${m.final?Math.round(m.score/50*100)+'%':'Jumlah akhir: belum ditentukan · Menunggu semakan: '+m.pending+' markah'} · Masa ${Math.floor(s.time/60)} minit ${s.time%60} saat · ${new Date(s.date).toLocaleDateString('ms-MY')}</p><p class="muted spaced">Markah respons terbuka dan cara kerja alternatif boleh diselaraskan pada rubrik di bawah.</p><div class="actions"><button class="primary" data-answer-again="${s.subject}:${s.set}">Jawab set ini semula</button><button class="secondary" data-page="performance">Prestasi</button></div></section><section class="card"><h2>Analisis topik</h2><div class="topic-stats">${Object.entries(analysis(s)).sort(([,a],[,b])=>a.score/a.max-b.score/b.max).map(([id,t])=>`<div class="topic-stat"><div class="row"><span>${e(topicInfo(s.subject,id)?.name||id)}</span><b>${t.pending?'Menunggu semakan':Math.round(t.score/t.max*100)+'%'}</b></div><div class="progress"><span style="width:${t.score/t.max*100}%"></span></div><button class="text-button" data-quick="${s.subject}:${id}">Ulang topik ini →</button></div>`).join('')}</div></section></div><section class="card spaced"><h2>Semakan mengikut soalan</h2><p class="muted spaced">Buka item untuk melihat bahan, jawapan kamu, isi dikesan dan rubrik. Pelarasan ibu bapa disimpan pada cubaan ini.</p>${p.questions.map((q,i)=>`<details class="result-detail"><summary>${questionLabel(q)} · ${e(q.topic)} · ${resolvedGrade(s,i).pending?'Menunggu semakan':adjustedGrade(s,i)+'/'+q.marks}${s.grades[i].review?' · cadangan':''}</summary><div class="spaced">${questionBody(q,s.answers[i],'r-'+i,true)}</div>${resolvedGrade(s,i).parentTotal?'<p class="notice">Jumlah soalan telah disahkan ibu bapa; pecahan komponen tidak diperincikan.</p>':feedback(q,resolvedGrade(s,i))}${manualFields(s,i)}<div class="adjust"><label for="adjust-${i}">Pelarasan ibu bapa (0–${q.marks})</label><input id="adjust-${i}" type="number" inputmode="decimal" min="0" max="${q.marks}" step="0.5" value="${resolvedGrade(s,i).pending?'':adjustedGrade(s,i)}"><button class="secondary" data-adjust="${i}" data-result="${s.id}">Simpan markah</button></div></details>`).join('')}</section>`;}
function performance(){let groups={};S.scores.forEach(s=>{let k=s.name+':'+s.subject+':'+s.set;if(!groups[k])groups[k]=[];groups[k].push(s);});let stats=Object.entries(S.stats),weak=weakest()[0];return title('Prestasi kamu','Bandingkan kemajuan sendiri. Setiap cubaan, markah terbaik dan masa disimpan.',`<button class="secondary" data-export>Eksport rekod</button>`)+`<div class="grid-four"><div class="card"><div class="stat-number">${S.stars} ★</div><div class="stat-label">Bintang</div></div><div class="card"><div class="stat-number">${S.scores.length}</div><div class="stat-label">Cubaan simulasi</div></div><div class="card"><div class="stat-number">${stats.reduce((a,[,v])=>a+v.total,0)}</div><div class="stat-label">Soalan kecil dilatih</div></div><div class="card"><div class="stat-number">${weak?statPct(weak[1])+'%':'—'}</div><div class="stat-label">${weak?e(topicInfo(...weak[0].split(':')).name):'Topik untuk ulang'}</div></div></div><div class="card spaced"><h2>Scoreboard · terkini & terbaik</h2><div class="filters spaced"><select id="score-filter" aria-label="Tapis subjek"><option value="all">Semua subjek</option>${Object.entries(SB.subjects).map(([id,s])=>`<option value="${id}" ${scoreFilter===id?'selected':''}>${e(s.name)}</option>`).join('')}</select></div><div class="table-scroll"><table class="data-table scoreboard"><thead><tr><th>Murid / Subjek</th><th>Set</th><th>Terkini</th><th>Terbaik</th><th>Cubaan</th><th>Peningkatan</th></tr></thead><tbody>${Object.values(groups).filter(g=>scoreFilter==='all'||g[0].subject===scoreFilter).map(g=>{let latest=g[0],finished=g.filter(s=>metrics(s).final),best=finished.length?Math.max(...finished.map(s=>metrics(s).score)):null,first=g[g.length-1],delta=metrics(latest).final&&metrics(first).final?metrics(latest).score-metrics(first).score:null;return `<tr><td>${e(latest.name)}<br><small>${e(SB.subjects[latest.subject].name)}</small></td><td>${latest.set}</td><td>${scoreText(latest)}</td><td>${best===null?'Menunggu semakan':best+'/50'}</td><td>${g.length}</td><td>${delta===null?'Belum ditentukan':(delta>0?'+':'')+delta+' markah'}</td></tr>`;}).join('')||'<tr><td colspan="6">Belum ada cubaan simulasi.</td></tr>'}</tbody></table></div></div><div class="grid spaced"><div class="card"><h2>Topik kuat & perlu diulang</h2><div class="topic-stats">${stats.sort(([,a],[,b])=>statPct(a)-statPct(b)).map(([k,v])=>{let [s,t]=k.split(':');return `<div class="topic-stat"><div class="row"><span>${e(SB.subjects[s].name+' · '+topicInfo(s,t).name)}</span><b>${statPct(v)}%</b></div><span class="muted">${v.correct}/${v.total} respons penuh tepat</span><button class="text-button" data-quick="${k}">Cuba sesi lain →</button></div>`;}).join('')||'<p class="muted">Cuba latih tubi untuk melihat topik kuat dan topik yang boleh diulang.</p>'}</div></div><div class="card"><h2>Sejarah cubaan</h2><div class="topic-stats">${S.scores.filter(s=>scoreFilter==='all'||s.subject===scoreFilter).map(s=>`<button class="topic-button" data-open-result="${s.id}"><strong>${e(s.name)} · ${e(SB.subjects[s.subject].name)} · Set ${s.set}</strong><small>Cubaan ${s.attempt} · ${scoreText(s)} · ${Math.floor(s.time/60)} minit · ${new Date(s.date).toLocaleDateString('ms-MY')}</small></button>`).join('')||'<p class="muted">Keputusan setiap set akan muncul di sini.</p>'}</div></div></div>`;}
function references(){let src=SB.sources.filter(s=>gallerySubject==='all'||s.subject===gallerySubject);return title('Bahan rujukan bergambar',SB.sources.length+' fail asal daripada arkib MPT dikekalkan. Klik gambar untuk besarkan.')+`<div class="filters"><select id="gallery-filter" aria-label="Tapis gambar"><option value="all">Semua gambar</option>${Object.entries(SB.subjects).map(([id,s])=>`<option value="${id}" ${gallerySubject===id?'selected':''}>${e(s.name)}</option>`).join('')}<option value="other">Lain-lain</option></select></div><div class="gallery">${src.map(s=>`<button data-image="${e(s.src)}"><img loading="lazy" src="${e(s.src)}" alt="Rujukan ${s.id}: ${e(s.name)}"><small>#${s.id} · ${e(SB.subjects[s.subject]?.name||'Lain-lain')}</small><small>${e(s.name)}</small></button>`).join('')}</div>`;}
function about(){return title('Format & rujukan','Struktur setiap subjek dipisahkan. Kertas simulasi mengandungi soalan latihan, bukannya kertas rasmi.')+`<div class="grid">${Object.entries(SB.subjects).map(([id,s])=>`<div class="card"><h2>${e(s.name)}</h2>${formatSummary(SB.papers[id+'-1'])}<p class="muted">${bank(id).length} situasi latihan · ${SB.topics[id].length} topik.</p></div>`).join('')}</div><div class="card spaced"><h2>Bahan asal & had semakan</h2><p class="spaced">${SB.sources.length} gambar rujukan anda dikekalkan. Rajah koordinat, carta, bentuk dan penyiasatan dibina sebagai SVG / jadual supaya tajam pada skrin kecil. Gambar penulisan menggunakan bahan yang anda beri.</p><p>Format utama disemak silang dengan jadual taklimat MPT4 yang dikongsi SK Muadzam Shah: Matematik A26/B24, Sains A10/B8/C32, BM A10/B10/C10/D20 dan English 6/7/7/7/8/15. <a href="https://fliphtml5.com/hvvdec/MATRIKS-PEMBELAJARAN/" target="_blank" rel="noopener noreferrer">Buka rujukan format</a>. Agihan markah item bagi model baharu ialah rubrik latihan. Respons Sains, cara kerja alternatif dan penulisan memerlukan semakan ibu bapa. Kiraan perkataan tidak boleh menentukan mutu karangan.</p><p class="muted spaced">Bank eksperimen 20 situasi baharu menggantikan fail pemboleh_ubah_lengkap_2.html yang belum diberikan. Kod lama hanya mempunyai 10 eksperimen dan ada ralat fakta; kandungan itu tidak dipindahkan.</p><button class="text-button" data-page="references">Lihat semua gambar</button></div>`;}
function render(){try{$('content').innerHTML=({home,practice,exam,performance,parent,references,about}[page]||home)();updateExamMap();}catch(err){$('content').innerHTML=`<div class="error-page"><h2>Halaman tidak dapat dibuka.</h2><p>${e(err.message)}</p><button class="secondary" data-page="home">Kembali ke Utama</button></div>`;console.error(err);}}
function getAnswerContext(key){if(key.startsWith('p-'))return {container:S.practice,idx:Number(key.slice(2)),q:S.practice.questions[Number(key.slice(2))]};if(key.startsWith('x-'))return {container:S.exam,idx:Number(key.slice(2)),q:paperFor(S.exam).questions[Number(key.slice(2))]};return null;}
function recordInput(el){let key=el.dataset.answer,c=getAnswerContext(key);if(!c)return;let i=Number(el.dataset.part),field=el.dataset.field;c.container.answers[c.idx]??={};c.container.answers[c.idx][i]??={};c.container.answers[c.idx][i][field]=el.value;save();const p=c.q.parts[i];if(p.type==='essay'&&$('wc-'+key+'-'+i))$('wc-'+key+'-'+i).innerHTML=wordCount(p,el.value);if(p.type==='coordinate'||c.q.diagram?.type==='bars')$('diagram-'+key).innerHTML=SB.diagram(c.q.diagram,{interactive:true,key,answers:c.container.answers[c.idx]});updateExamMap();}
document.addEventListener('input',evt=>{let el=evt.target;if(el.dataset.answer)recordInput(el);else if(el.id==='name'){S.name=el.value;save();}});
document.addEventListener('change',evt=>{let el=evt.target;if(el.type==='radio'&&el.dataset.answer)recordInput(el);if(el.dataset.check){let c=getAnswerContext(el.dataset.check),p=Number(el.dataset.part);c.container.answers[c.idx]??={};c.container.answers[c.idx][p]??={};c.container.answers[c.idx][p].checks??={};c.container.answers[c.idx][p].checks[el.dataset.checkIndex]=el.checked;save();}if(el.id==='exam-subject'){examSubject=el.value;render();}if(el.name==='set'){selectedSet=Number(el.value);render();}if(el.id==='flag'&&S.exam){S.exam.flags[S.exam.index]=el.checked;save();updateExamMap();}if(el.id==='gallery-filter'){gallerySubject=el.value;render();}if(el.id==='score-filter'){scoreFilter=el.value;render();}});
document.addEventListener('keydown',evt=>{if((evt.key==='Enter'||evt.key===' ')&&(evt.target.dataset.coordinate||evt.target.dataset.chart)){evt.preventDefault();evt.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('click',evt=>{let b=evt.target.closest('button,[data-coordinate],[data-chart]');if(!b||b.disabled)return;let d=b.dataset;
if(d.page){go(d.page);return;}if(d.subject){selectedSubject=d.subject;selectedTopic=null;go('practice');return;}if(d.topic){selectedTopic=d.topic;render();return;}if(d.quick){[selectedSubject,selectedTopic]=d.quick.split(':');if(S.practice){modal('<h2>Ada sesi yang tersimpan</h2><p>Sambung sesi terdahulu atau mula sesi baharu bagi topik ini.</p><div class="actions"><button class="primary" data-resume-practice>Sambung sesi tersimpan</button><button class="secondary" data-new-practice>Mula sesi baharu</button></div>');}else go('practice');return;}
if('resumePractice'in d){$('modal').close();go('practice');}if('newPractice'in d){S.practice=null;save();$('modal').close();go('practice');}
if('practiceBack'in d){selectedSubject=null;selectedTopic=null;render();}if('topicBack'in d){selectedTopic=null;render();}if('startPractice'in d)startPractice();
if('leavePractice'in d)go('home');if('finishPractice'in d){selectedSubject=S.practice.subject;logActivity('practice_finish',{subject:S.practice.subject,topic:S.practice.topic,answered:Object.keys(S.practice.graded).length,total:S.practice.questions.length});S.practice=null;selectedTopic=null;save();render();}if('repeatPractice'in d){selectedSubject=S.practice.subject;selectedTopic=S.practice.topic;S.practice=null;startPractice();}
if('checkPractice'in d)checkPractice();if('nextPractice'in d){S.practice.index++;save();render();}
if('hint'in d){let P=S.practice,h=P.hints[P.index]||0;if(h<3){P.hints[P.index]=h+1;save();render();}}
if('related'in d){let P=S.practice,old=P.questions[P.index];let next=choose(P.subject,P.topic,1,P.questions.map(q=>q.id))[0];if(next){P.questions[P.index]=next;delete P.answers[P.index];delete P.graded[P.index];delete P.hints[P.index];delete P.clocks?.[P.index];delete P.revealed?.[P.index];delete P.assisted?.[P.index];save();render();}else toast('Cuba sesi baharu untuk lebih banyak variasi.');}
if('bonus'in d){let today=new Date().toLocaleDateString('en-CA');if(S.bonusDate!==today){S.bonusDate=today;S.stars+=3;save();toast('+3 ★ bonus hari ini');}else toast('Bonus hari ini sudah diambil.');}
if('beginExam'in d)beginExam();if(d.examIndex!==undefined){S.exam.index=Number(d.examIndex);save();render();}if(d.section){let p=paperFor(S.exam);S.exam.index=p.questions.findIndex(q=>q.section===d.section);save();render();}
if('examNext'in d){S.exam.index++;save();render();}if('examPrev'in d){S.exam.index--;save();render();}if('submitConfirm'in d)confirmSubmit();if('submitFinal'in d)submitExam();if('returnExam'in d)$('modal').close();
if(d.coordinate){let c=getAnswerContext(d.coordinate);c.container.answers[c.idx]??={};c.container.answers[c.idx][0]={x:Number(d.x),y:Number(d.y)};save();render();}if(d.chart){let c=getAnswerContext(d.chart),i=Number(d.part);c.container.answers[c.idx]??={};c.container.answers[c.idx][i]={value:d.value};save();render();}
if(d.zoom){const idx=Number(d.zoom.split('-')[1]),q=d.zoom.startsWith('p-')?S.practice.questions[idx]:d.zoom.startsWith('x-')?paperFor(S.exam).questions[idx]:paperFor(S.scores.find(s=>s.id===resultId)).questions[idx];modal('<h2>Rajah penuh — untuk melihat</h2>'+SB.diagram(q.diagram,{interactive:false,key:'zoom'}));}
if(d.image)modal(`<img src="${e(d.image)}" alt="Gambar rujukan diperbesarkan">`);
if(d.openResult){resultId=d.openResult;go('exam');}if('resultBack'in d){resultId=null;go('performance');}if(d.answerAgain){[examSubject,selectedSet]=d.answerAgain.split(':');selectedSet=Number(selectedSet);resultId=null;go('exam');}
if(d.adjust!==undefined){let s=S.scores.find(x=>x.id===d.result),i=Number(d.adjust),raw=$('adjust-'+i).value,value=Number(raw),p=paperFor(s);if(!raw.trim()){toast('Isi markah selepas semakan; kosong bermaksud belum dinilai.');return;}if(!Number.isFinite(value)||value<0||value>p.questions[i].marks){toast('Isi markah dalam julat yang diberi.');return;}s.adjustments[i]=value;s.score=p.questions.reduce((a,q,j)=>a+adjustedGrade(s,j),0);s.percentage=metrics(s).final?Math.round(s.score/50*100):null;save();render();toast('Pelarasan ibu bapa tersimpan.');}
if('finishReading'in d)beginAnswerClock();
if('selfCheck'in d)toast('Jika maksud sama, catat untuk semakan ibu bapa. Bintang dan markah tidak berubah.');
if('worked'in d){S.practice.revealed??={};S.practice.revealed[S.practice.index]=true;checkPractice(true,true);document.querySelector('.sample-answer')?.setAttribute('open','');}
if('retry'in d){const P=S.practice,q=P.questions[P.index];P.recorded??={};P.recorded[q.id]=true;delete P.graded[P.index];delete P.answers[P.index];P.revealed??={};P.revealed[P.index]=true;P.clocks[P.index]={phase:'answer',limit:SB.practiceBudget(q),started:Date.now(),deadline:Date.now()+SB.practiceBudget(q)*1000,retry:true};save();render();}
if(d.chip){const c=getAnswerContext(d.key);c.container.answers[c.idx]??={};c.container.answers[c.idx][Number(d.part)]??={};c.container.answers[c.idx][Number(d.part)].value=d.chip;S.practice.assisted??={};S.practice.assisted[S.practice.index]=true;save();render();}
if(d.manual){const s=S.scores.find(x=>x.id===d.result),[i,j,k]=d.manual.split(':').map(Number),raw=$('manual-'+i+'-'+j+'-'+k).value,v=Number(raw),max=s.grades[i].parts[j].details[k].max;if(!raw.trim()||!Number.isFinite(v)||v<0||v>max){toast('Isi markah komponen dalam julat yang diberi.');return;}s.manualMarks??={};s.manualMarks[i]??={};s.manualMarks[i][j]??={};s.manualMarks[i][j][k]=v;const m=metrics(s);s.score=m.score;s.percentage=m.final?Math.round(m.score/50*100):null;save();render();}
if('setParentPin'in d){let pin=$('new-parent-pin')?.value.trim();if(!/^\d{4}$/.test(pin)){toast('Gunakan tepat 4 digit.');return;}S.parentPin=pin;parentUnlocked=true;save();render();toast('PIN ibu bapa disimpan.');}if('unlockParent'in d){let pin=$('parent-pin')?.value.trim();if(pin!==S.parentPin){toast('PIN tidak betul.');return;}parentUnlocked=true;render();}if('lockParent'in d){parentUnlocked=false;render();}if('saveChild'in d){S.name=$('child-name')?.value.trim()||S.name;save();render();toast('Nama anak disimpan.');}if('largeType'in d){S.largeType=!S.largeType;document.body.classList.toggle('large-type',S.largeType);save();}
if('export'in d){let blob=new Blob([JSON.stringify(S,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='study-buddy-rekod.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
});
document.addEventListener('visibilitychange',()=>{if(!S.practice&&!S.exam)return;logActivity(document.hidden?'app_hidden':'app_visible',{mode:S.exam?'exam':'practice'});save();});
window.addEventListener('hashchange',()=>{let p=location.hash.slice(1);if(p!==page){page=p||'home';render();document.querySelectorAll('#main-nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));}});
setInterval(()=>{if(S.practice&&page==='practice')tickPractice();if(S.exam){if(Date.now()>=S.exam.deadline){submitExam(true);return;}if($('timer'))$('timer').textContent=timeLeft(S.exam.deadline);}},1000);
window.StudyBuddy={state:()=>S,bank,go,grade:SB.gradeQuestion,metrics};
if(S.exam&&Date.now()>=S.exam.deadline){submitExam(true);}else go(S.exam?'exam':S.practice?'practice':location.hash.slice(1)||'home');save();
})();
